        events.append((y, 1, x, x + l))
        events.append((y + l, -1, x, x + l))
    events.sort(key=lambda e: e[0])

    total_area = sum(l * l for x, y, l in squares)
    target = total_area / 2.0

    # Sweep through y-events, computing cumulative area below each y
    cumulative_area = 0.0
    prev_y = events[0][0]

    # Active intervals: list of [x1, x2]
    active = []

    def compute_width():
        if not active:
            return 0.0
        # Merge intervals and sum lengths
        active.sort()
        merged = []
        cx1, cx2 = active[0]
        for x1, x2 in active[1:]:
            if x1 <= cx2:
                cx2 = max(cx2, x2)
            else:
                merged.append((cx1, cx2))
                cx1, cx2 = x1, x2
        merged.append((cx1, cx2))
        return sum(x2 - x1 for x1, x2 in merged)

    prev_width = 0.0
    area_at_y = {}
    area_at_y[prev_y] = 0.0

    i = 0
    n = len(events)
    while i < n:
        current_y = events[i][0]

        # Add area from prev_y to current_y
        if current_y > prev_y:
            cumulative_area += prev_width * (current_y - prev_y)

        # Process all events at current_y
        new_active = []
        while i < n and events[i][0] == current_y:
            _, sign, x1, x2 = events[i]
            if sign == 1:
                new_active.append([x1, x2])
            else:
                # Remove [x1, x2] from new_active
                for j in range(len(new_active)):
                    if new_active[j][0] == x1 and new_active[j][1] == x2:
                        del new_active[j]
                        break
            i += 1

        active = new_active
        prev_width = compute_width()
        prev_y = current_y
        area_at_y[current_y] = cumulative_area

    # Now find y such that area_below(y) = target
    y_list = sorted(area_at_y.keys())

    # Check if target is at the last y
    if area_at_y[y_list[-1]] <= target + 1e-10:
        return float(y_list[-1])

    # Find the interval where target is crossed
    for idx in range(len(y_list) - 1):
        a1 = area_at_y[y_list[idx]]
        a2 = area_at_y[y_list[idx + 1]]
        if a1 <= target <= a2:
            y1 = y_list[idx]
            y2 = y_list[idx + 1]
            if y2 > y1:
                width = (a2 - a1) / (y2 - y1)
                if width > 0:
                    dy = (target - a1) / width
                    return float(y1 + dy)
            return float(y2)

    return float(y_list[-1])
