def beautifulNumbers(l: int, r: int):
    from functools import lru_cache
    from math import gcd

    def count(n):
        if n <= 0:
            return 0
        digits = list(map(int, str(n)))
        length = len(digits)

        @lru_cache(maxsize=None)
        def dp(pos, tight, sum_d, prod_d):
            if pos == length:
                return 1 if sum_d > 0 and prod_d % sum_d == 0 else 0

            limit = digits[pos] if tight else 9
            total = 0
            for d in range(limit + 1):
                new_tight = tight and (d == limit)
                new_sum = sum_d + d
                new_prod = prod_d * d if prod_d != 0 else (d if d != 0 else 0)
                # If prod_d is 0, it stays 0. Otherwise multiply.
                if prod_d == 0:
                    new_prod = 0
                else:
                    new_prod = prod_d * d

                total += dp(pos + 1, new_tight, new_sum, new_prod)
            return total

        return dp(0, True, 0, 0)

    return count(r) - count(l - 1)
