        if n == 0:
            return False
        digits = []
        num = n
        while num > 0:
            digits.append(num % 10)
            num //= 10
        digit_sum = sum(digits)
        if digit_sum == 0:
            return False
        digit_product = 1
        for d in digits:
            digit_product *= d
        return digit_product % digit_sum == 0

    count = 0
    for num in range(l, r + 1):
        if is_beautiful(num):
            count += 1
    return count
